insert into public.recipes (name, kind, ingredients, ingredient_lines, steps) values
  ('Tacos', 'old', ARRAY['Ground beef','Tortillas','Cheese','Lettuce']::text[], ARRAY['1 lb ground beef','8 small tortillas','1 cup shredded cheese','Half a head of lettuce, shredded']::text[], ARRAY['Brown the beef over medium-high heat, breaking it up as it cooks.','Stir in the taco seasoning and a splash of water; simmer until thickened.','Warm the tortillas in a dry pan, 20 seconds a side.','Build each taco: beef, cheese, lettuce.']::text[]),
  ('Spaghetti', 'old', ARRAY['Pasta','Tomato sauce','Ground beef','Parmesan']::text[], ARRAY['400 g spaghetti','1 jar tomato sauce','1 lb ground beef','Parmesan to finish']::text[], ARRAY['Salt the pasta water heavily and bring it to a boil.','Brown the beef, then pour in the sauce and simmer while the pasta cooks.','Cook the spaghetti one minute short of the box time.','Toss the pasta through the sauce with a splash of pasta water. Grate parmesan over.']::text[]),
  ('Shepherd’s Pie', 'old', ARRAY['Ground beef','Potatoes','Peas','Carrots']::text[], ARRAY['1 lb ground beef','6 potatoes','1 cup frozen peas','2 carrots, diced']::text[], ARRAY['Boil the potatoes until a knife slides through; mash with butter.','Brown the beef with the carrots, then stir in the peas.','Spread the mince in a baking dish and top with the mash, forking the surface.','Bake at 200°C for 25 minutes, until the peaks brown.']::text[]),
  ('Butter Chicken', 'old', ARRAY['Chicken','Cream','Tomato','Rice']::text[], ARRAY['4 chicken thighs, cubed','1 cup cream','1 can crushed tomato','2 cups rice']::text[], ARRAY['Sear the chicken in batches; set aside.','Soften the onion and spices, add the tomato, simmer 10 minutes.','Return the chicken, stir in the cream, simmer until it coats a spoon.','Serve over rice.']::text[]),
  ('Homemade Pizza', 'old', ARRAY['Dough','Tomato sauce','Mozzarella']::text[], ARRAY['1 ball pizza dough','Half a cup tomato sauce','200 g mozzarella']::text[], ARRAY['Heat the oven as high as it goes with a tray inside.','Stretch the dough thin; it should be translucent in the middle.','Sauce thinly, then tear the mozzarella over.','Bake 8–10 minutes until the crust is blistered.']::text[]),
  ('Chicken Curry', 'old', ARRAY['Chicken','Curry paste','Coconut milk','Rice']::text[], ARRAY['4 chicken thighs','2 tbsp curry paste','1 can coconut milk','2 cups rice']::text[], ARRAY['Fry the curry paste in a little oil until it smells fragrant.','Add the chicken and turn it through the paste.','Pour in the coconut milk and simmer 20 minutes.','Serve over rice.']::text[]),
  ('Stir Fry', 'old', ARRAY['Rice','Chicken','Mixed veggies','Soy sauce']::text[], ARRAY['2 cups rice','2 chicken breasts, sliced','1 bag mixed veggies','3 tbsp soy sauce']::text[], ARRAY['Get the pan hotter than feels sensible.','Sear the chicken in one layer; do not stir for the first minute.','Add the vegetables and keep everything moving.','Splash in the soy sauce at the very end so it steams rather than burns.']::text[]),
  ('Grilled Salmon', 'old', ARRAY['Salmon','Lemon','Potatoes']::text[], ARRAY['4 salmon fillets','1 lemon','6 baby potatoes per person']::text[], ARRAY['Boil the potatoes, then crush them lightly and crisp in a hot pan.','Dry the salmon skin thoroughly and salt it.','Skin-side down in a hot pan for 4 minutes, then 1 minute on the flesh.','Squeeze the lemon over everything.']::text[]),
  ('Lemon Orzo with Feta', 'new', ARRAY['Pasta','Lemon','Cheese']::text[], ARRAY['300 g orzo','1 lemon','150 g feta']::text[], ARRAY['Cook the orzo in salted water until just tender.','Off the heat, stir through lemon zest, juice and olive oil.','Crumble the feta over and fold once — it should stay in pieces.']::text[]),
  ('Black Bean Tacos', 'new', ARRAY['Tortillas','Tomato','Cheese']::text[], ARRAY['8 tortillas','1 can black beans','2 tomatoes','1 cup cheese']::text[], ARRAY['Fry the drained beans with cumin until they start to catch.','Mash about half of them so the filling holds together.','Warm the tortillas and fill; top with chopped tomato and cheese.']::text[]),
  ('Coconut Chickpea Stew', 'new', ARRAY['Coconut milk','Tomato','Rice']::text[], ARRAY['1 can chickpeas','1 can coconut milk','1 can tomato','2 cups rice']::text[], ARRAY['Soften onion and garlic, add curry powder and cook it out.','Add the chickpeas, tomato and coconut milk.','Simmer 25 minutes until it thickens. Serve over rice.']::text[]),
  ('Sheet Pan Sausage and Peppers', 'new', ARRAY['Potatoes','Mixed veggies']::text[], ARRAY['6 sausages','4 potatoes, cubed','2 peppers, sliced']::text[], ARRAY['Heat the oven to 220°C.','Toss everything with oil, salt and dried oregano on one tray.','Roast 35 minutes, turning once, until the edges char.']::text[]);
insert into public.proteins (name, ingredients, ingredient_lines, steps) values
  ('Roast chicken thighs', ARRAY['Chicken']::text[], ARRAY['6 bone-in chicken thighs']::text[], ARRAY['Dry the skin and salt generously.','Skin-side up at 220°C for 35 minutes, no turning.']::text[]),
  ('Pan-seared salmon', ARRAY['Salmon']::text[], ARRAY['4 salmon fillets']::text[], ARRAY['Dry the skin thoroughly and salt it.','Skin-side down in a hot pan 4 minutes, 1 minute on the flesh.']::text[]),
  ('Garlic butter shrimp', ARRAY['Shrimp']::text[], ARRAY['500 g shrimp','3 cloves garlic','2 tbsp butter']::text[], ARRAY['Melt the butter, add the garlic, wait until it smells sweet.','Add the shrimp; they are done the moment they curl.']::text[]),
  ('Crispy tofu', ARRAY['Tofu']::text[], ARRAY['1 block firm tofu','2 tbsp cornstarch']::text[], ARRAY['Press the tofu 20 minutes, then cube and toss in cornstarch.','Shallow fry until each face is golden.']::text[]),
  ('Pork chops', ARRAY['Pork']::text[], ARRAY['4 bone-in pork chops']::text[], ARRAY['Salt an hour ahead if you can.','Hard sear both sides, then rest 5 minutes before slicing.']::text[]),
  ('Beef meatballs', ARRAY['Ground beef']::text[], ARRAY['1 lb ground beef','1 egg','Half a cup breadcrumbs']::text[], ARRAY['Mix gently — overworking makes them bouncy.','Roll golf-ball sized, brown all over, finish in the oven 10 minutes.']::text[]);
insert into public.sides (name, ingredients, ingredient_lines, steps) values
  ('Garlic rice', ARRAY['Rice']::text[], ARRAY['2 cups rice','3 cloves garlic']::text[], ARRAY['Fry the garlic in butter until barely golden.','Stir through freshly cooked rice.']::text[]),
  ('Roasted broccoli', ARRAY['Broccoli']::text[], ARRAY['2 heads broccoli']::text[], ARRAY['Toss with oil and salt.','220°C for 20 minutes — the charred bits are the point.']::text[]),
  ('Mashed potatoes', ARRAY['Potatoes']::text[], ARRAY['6 potatoes','100 g butter']::text[], ARRAY['Boil until a knife slides through with no resistance.','Mash with warm butter; cold butter makes them gluey.']::text[]),
  ('Simple green salad', ARRAY['Lettuce','Lemon']::text[], ARRAY['1 head lettuce','1 lemon']::text[], ARRAY['Dress with lemon, olive oil and salt just before serving.']::text[]),
  ('Buttered noodles', ARRAY['Pasta','Parmesan']::text[], ARRAY['300 g egg noodles','50 g butter','Parmesan']::text[], ARRAY['Cook the noodles, drain, toss with butter and a little pasta water.','Grate parmesan over off the heat.']::text[]),
  ('Honey glazed carrots', ARRAY['Carrots']::text[], ARRAY['6 carrots','2 tbsp honey']::text[], ARRAY['Roast the carrots 20 minutes.','Brush with honey and give them 5 minutes more.']::text[]);
